/* ================== PARAMETERS (SSMS) ================== */
DECLARE @StartDate NVARCHAR(20) = '2026-01-01';
DECLARE @EndDate   NVARCHAR(20) = '2026-12-31';
DECLARE @WhsCode   NVARCHAR(50) = NULL;  -- NULL: T?t c? kho, ho?c nh?p m kho (VD: 'W01')
DECLARE @StartItemCode NVARCHAR(50) = NULL; -- NULL: Khng gi?i h?n t? m
DECLARE @EndItemCode   NVARCHAR(50) = NULL; -- NULL: Khng gi?i h?n ??n m

-- X? l an ton Ngy Thng
DECLARE @RealStartDate DATETIME = NULL;
DECLARE @RealEndDate DATETIME = NULL;
IF LEN(ISNULL(@StartDate, '')) > 0 SET @RealStartDate = TRY_CONVERT(DATETIME, @StartDate);
IF LEN(ISNULL(@EndDate, '')) > 0   SET @RealEndDate   = TRY_CONVERT(DATETIME, @EndDate);

SELECT    T_Result.[Tên_Chi_Nhánh],    T_Result.[Mã_Kho],    T_Result.[Tên_Kho],    T_Result.[Mã_Tài_Khoản],    T_Result.[Tên_Tài_Khoản],    T_Result.[Mã_Vật_Tư],    T_Result.[Tên_Vật_Tư],    T_Result.[Nhóm_Vật_Tư],    T_Result.[Tên_Nhóm_Vật_Tư],        T_Result.[ĐVT_Kho],    T_Result.[ĐVT_Mua],    T_Result.[Tỉ_Lệ_ĐVT_Mua],    T_Result.[ĐVT_Bán],    T_Result.[Tỉ_Lệ_ĐVT_Bán],    T_Result.[Số_Lô_Batch],    -- Bỏ NULLIF để hiện số 0 bình thường    T_Result.[Opening Qty],    NULLIF(T_Result.[Opening Value], 0) AS [Opening Value],        T_Result.[Input Qty],    NULLIF(T_Result.[Input Value], 0) AS [Input Value],        T_Result.[Output Qty],    NULLIF(T_Result.[Output Value], 0) AS [Output Value],        T_Result.[Ending Qty],    -- LOGIC TÍNH GIÁ TRỊ TỒN CUỐI    NULLIF(        CASE             WHEN T_Result.[IsBatchRow] = 1 THEN NULL             WHEN ROUND(T_Result.[Ending Qty], 4) = 0 THEN 0            ELSE ROUND(T_Result.[Ending Qty] * ISNULL(T_Result.[Calculated_Unit_Cost], 0), 2)        END    , 0) AS [Ending Value],    NULLIF(ROUND(ISNULL(T_Result.[Calculated_Unit_Cost], 0), 4), 0) AS [Giá_Vốn_BQ_Cuối_Kỳ],        CASE WHEN T_Result.[IsBatchRow] = 0 THEN ISNULL(@EndDate, N'Kỳ hiện tại') ELSE NULL END AS [Thời_Điểm_Tính_Giá_Vốn]FROM (    SELECT         T_Main.*,        CASE WHEN T_Main.IsBatchRow = 0 THEN             SUM(CASE WHEN T_Main.IsBatchRow = 0 THEN T_Main.[Raw Ending Value] ELSE 0 END) OVER (PARTITION BY T_Main.[Mã_Vật_Tư]) /             NULLIF(SUM(CASE WHEN T_Main.IsBatchRow = 0 THEN T_Main.[Ending Qty] ELSE 0 END) OVER (PARTITION BY T_Main.[Mã_Vật_Tư]), 0)        ELSE NULL END AS [Calculated_Unit_Cost]    FROM (        -- BLOCK 1: DÒNG TỔNG        SELECT              ISNULL((SELECT TOP 1 T_BPL.BPLName FROM OWHS T_WHS INNER JOIN OBPL T_BPL ON T_WHS.BPLid = T_BPL.BPLId WHERE T_WHS.WhsCode = T0.Warehouse), N'Trụ sở chính') AS [Tên_Chi_Nhánh],             T0.Warehouse AS [Mã_Kho],            (SELECT Whsname FROM OWHS WHERE Whscode = T0.Warehouse) AS [Tên_Kho],            T10.BalInvntAc AS [Mã_Tài_Khoản],            (SELECT AcctName FROM OACT WHERE AcctCode = T10.BalInvntAc) AS [Tên_Tài_Khoản],            T0.ItemCode AS [Mã_Vật_Tư],            T1.ItemName AS [Tên_Vật_Tư],            T1.ItmsGrpCod AS [Nhóm_Vật_Tư],            T10.ItmsGrpNam AS [Tên_Nhóm_Vật_Tư],                        T1.InvntryUom AS [ĐVT_Kho],            T1.BuyUnitMsr AS [ĐVT_Mua],            T1.NumInBuy AS [Tỉ_Lệ_ĐVT_Mua],            T1.SalUnitMsr AS [ĐVT_Bán],            T1.NumInSale AS [Tỉ_Lệ_ĐVT_Bán],            N'👉 [ TỔNG KHO ]' AS [Số_Lô_Batch],            0 AS [IsBatchRow],             SUM(CASE WHEN T0.DocDate < @RealStartDate AND @RealStartDate IS NOT NULL THEN T0.InQty - T0.OutQty ELSE 0 END) AS [Opening Qty],            SUM(CASE WHEN T0.DocDate < @RealStartDate AND @RealStartDate IS NOT NULL THEN T0.TransValue ELSE 0 END) AS [Opening Value],                        SUM(CASE WHEN (T0.DocDate >= @RealStartDate OR @RealStartDate IS NULL) AND (T0.DocDate <= @RealEndDate OR @RealEndDate IS NULL) THEN T0.InQty ELSE 0 END) AS [Input Qty],            SUM(CASE WHEN (T0.DocDate >= @RealStartDate OR @RealStartDate IS NULL) AND (T0.DocDate <= @RealEndDate OR @RealEndDate IS NULL) AND T0.TransValue > 0 THEN T0.TransValue ELSE 0 END) AS [Input Value],                        SUM(CASE WHEN (T0.DocDate >= @RealStartDate OR @RealStartDate IS NULL) AND (T0.DocDate <= @RealEndDate OR @RealEndDate IS NULL) THEN T0.OutQty ELSE 0 END) AS [Output Qty],            SUM(CASE WHEN (T0.DocDate >= @RealStartDate OR @RealStartDate IS NULL) AND (T0.DocDate <= @RealEndDate OR @RealEndDate IS NULL) AND T0.TransValue < 0 THEN -T0.TransValue ELSE 0 END) AS [Output Value],                        SUM(CASE WHEN T0.DocDate <= @RealEndDate OR @RealEndDate IS NULL THEN T0.InQty - T0.OutQty ELSE 0 END) AS [Ending Qty],            SUM(CASE WHEN T0.DocDate <= @RealEndDate OR @RealEndDate IS NULL THEN T0.TransValue ELSE 0 END) AS [Raw Ending Value]        FROM OINM T0         INNER JOIN OITM T1 ON T0.ItemCode = T1.ItemCode        INNER JOIN OITB T10 ON T1.ItmsGrpCod = T10.ItmsGrpCod        WHERE T1.ManBtchNum = 'Y'           AND (T0.Warehouse = @WhsCode OR @WhsCode IS NULL)           AND (T0.ItemCode >= @StartItemCode OR @StartItemCode IS NULL)             AND (T0.ItemCode <= @EndItemCode OR @EndItemCode IS NULL)          AND (T0.DocDate <= @RealEndDate OR @RealEndDate IS NULL)        GROUP BY T0.ItemCode, T1.ItemName, T0.Warehouse, T1.ItmsGrpCod, T10.ItmsGrpNam, T10.BalInvntAc, T1.InvntryUom, T1.BuyUnitMsr, T1.NumInBuy, T1.SalUnitMsr, T1.NumInSale        UNION ALL        -- BLOCK 2: DÒNG CHI TIẾT LÔ        SELECT              ISNULL((SELECT TOP 1 T_BPL.BPLName FROM OWHS T_WHS INNER JOIN OBPL T_BPL ON T_WHS.BPLid = T_BPL.BPLId WHERE T_WHS.WhsCode = T1.WhsCode), N'Trụ sở chính') AS [Tên_Chi_Nhánh],             T1.WhsCode AS [Mã_Kho],            (SELECT Whsname FROM OWHS WHERE Whscode = T1.WhsCode) AS [Tên_Kho],            T10.BalInvntAc AS [Mã_Tài_Khoản],            (SELECT AcctName FROM OACT WHERE AcctCode = T10.BalInvntAc) AS [Tên_Tài_Khoản],            T1.ItemCode AS [Mã_Vật_Tư],            T2.ItemName AS [Tên_Vật_Tư],            T2.ItmsGrpCod AS [Nhóm_Vật_Tư],            T10.ItmsGrpNam AS [Tên_Nhóm_Vật_Tư],            T2.InvntryUom AS [ĐVT_Kho],            T2.BuyUnitMsr AS [ĐVT_Mua],            T2.NumInBuy AS [Tỉ_Lệ_ĐVT_Mua],            T2.SalUnitMsr AS [ĐVT_Bán],            T2.NumInSale AS [Tỉ_Lệ_ĐVT_Bán],            T1.BatchNum AS [Số_Lô_Batch],            1 AS [IsBatchRow],             0 AS [Opening Qty],             0 AS [Opening Value],                        SUM(CASE WHEN (CONVERT(DATETIME, T1.DocDate) >= @RealStartDate OR @RealStartDate IS NULL) AND (CONVERT(DATETIME, T1.DocDate) <= @RealEndDate OR @RealEndDate IS NULL) AND T1.Direction = 0 THEN T1.Quantity ELSE 0 END) AS [Input Qty],            0 AS [Input Value],                        SUM(CASE WHEN (CONVERT(DATETIME, T1.DocDate) >= @RealStartDate OR @RealStartDate IS NULL) AND (CONVERT(DATETIME, T1.DocDate) <= @RealEndDate OR @RealEndDate IS NULL) AND T1.Direction = 1 THEN T1.Quantity ELSE 0 END) AS [Output Qty],            0 AS [Output Value],                        SUM(CASE WHEN CONVERT(DATETIME, T1.DocDate) <= @RealEndDate OR @RealEndDate IS NULL THEN (CASE WHEN T1.Direction = 0 THEN T1.Quantity ELSE -T1.Quantity END) ELSE 0 END) AS [Ending Qty],            0 AS [Raw Ending Value]        FROM IBT1 T1         INNER JOIN OITM T2 ON T1.ItemCode = T2.ItemCode        INNER JOIN OITB T10 ON T2.ItmsGrpCod = T10.ItmsGrpCod        WHERE T2.ManBtchNum = 'Y'          AND (T1.WhsCode = @WhsCode OR @WhsCode IS NULL)           AND (T1.ItemCode >= @StartItemCode OR @StartItemCode IS NULL)             AND (T1.ItemCode <= @EndItemCode OR @EndItemCode IS NULL)          AND (CONVERT(DATETIME, T1.DocDate) <= @RealEndDate OR @RealEndDate IS NULL)        GROUP BY T1.ItemCode, T2.ItemName, T1.WhsCode, T1.BatchNum, T2.ItmsGrpCod, T10.ItmsGrpNam, T10.BalInvntAc, T2.InvntryUom, T2.BuyUnitMsr, T2.NumInBuy, T2.SalUnitMsr, T2.NumInSale    ) T_Main) T_ResultWHERE ROUND(T_Result.[Opening Qty], 4) <> 0    OR ROUND(T_Result.[Input Qty], 4) <> 0    OR ROUND(T_Result.[Output Qty], 4) <> 0    OR ROUND(T_Result.[Ending Qty], 4) <> 0ORDER BY     T_Result.[Mã_Vật_Tư],     T_Result.[Mã_Kho],     T_Result.[IsBatchRow] ASC,     T_Result.[Số_Lô_Batch]